#include <stdio.h>

int main(void) {
    double x;
    if (scanf("%lf", &x) != 1) { return 1; }
    printf("%.2f\n", x);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a, b;
    if (scanf("%d %d", &a, &b) != 2) { return 1; }
    printf("%d\n", a + b);
    return 0;
}

#include <stdio.h>

int main(void) {
    double w, h;
    if (scanf("%lf %lf", &w, &h) != 2) { return 1; }
    printf("%.2f\n", w * h);
    return 0;
}

#include <stdio.h>

int main(void) {
    int age;
    if (scanf("%d", &age) != 1) { puts("Invalid"); }
    else if (age < 0 || age > 120) { puts("Invalid"); }
    else { puts("Valid"); }
    return 0;
}

#include <stdio.h>

int main(void) {
    double a, b;
    if (scanf("%lf %lf", &a, &b) != 2 || b == 0) { puts("Invalid"); }
    else { printf("%.2f\n", a / b); }
    return 0;
}
